INSERT INTO `business_packages` (`id`, `slug`, `name`, `description`, `price_kzt`, `duration_days`, `benefits_json`, `limits_json`, `kind`, `billing`, `max_photos`, `free_service_listing`, `priority_boost`, `is_active`, `sort_order`, `created_at`) VALUES
(1, 'business-pro', 'Бизнес-пакет', 'Премиум-возможности для ИП и ТОО на Zakopeyki: приоритет в выдаче, больше фото, бесплатная публикация услуг и бейдж проверенного бизнеса.', 9990, 30, '[\"Бейдж «Проверенный бизнес»\",\"Приоритет в каталоге и поиске\",\"До 10 фото в объявлении\",\"Бесплатная публикация услуг\",\"Расширенная витрина продавца\"]', NULL, 'plan', 'period', 10, 1, 1, 0, 1, '2026-08-20 16:33:09'),
(2, 'business-month', 'Бизнес-пакет · 1 месяц', 'Загрузите каталог один раз — остальное Zakopeyki сделает автоматически.', 29900, 30, '[\"Безлимитные активные объявления\",\"Каталог до 50 000 товаров, до 5 000 новых объявлений в сутки\",\"Автозагрузка XML \\/ CSV \\/ XLSX \\/ YML \\/ API \\/ URL, синхронизация до 1 раза в час\",\"AI-инфографика 1 000\\/мес, описания и SEO 5 000\\/мес, оптимизация 5 000\\/мес\",\"Виртуальная примерка 300\\/мес\",\"100 бесплатных поднятий объявлений в месяц\",\"Бизнес-витрина, аналитика 12 месяцев, API и вебхуки\",\"До 5 сотрудников и приоритетная поддержка\"]', '{\"catalog\":50000,\"listings_per_day\":5000,\"sync_per_hour\":1,\"ai_infographic\":1000,\"ai_copy\":5000,\"ai_optimize\":5000,\"ai_tryon\":300,\"boosts\":100,\"staff\":5,\"analytics_months\":12,\"api\":1}', 'plan', 'period', 10, 1, 1, 1, 10, '2026-08-22 17:05:29'),
(3, 'business-3m', 'Бизнес-пакет · 3 месяца', 'Выгоднее месяца: профессиональный тариф на квартал.', 79900, 90, '[\"Безлимитные активные объявления\",\"Каталог до 50 000 товаров, до 5 000 новых объявлений в сутки\",\"Автозагрузка XML \\/ CSV \\/ XLSX \\/ YML \\/ API \\/ URL, синхронизация до 1 раза в час\",\"AI-инфографика 1 000\\/мес, описания и SEO 5 000\\/мес, оптимизация 5 000\\/мес\",\"Виртуальная примерка 300\\/мес\",\"100 бесплатных поднятий объявлений в месяц\",\"Бизнес-витрина, аналитика 12 месяцев, API и вебхуки\",\"До 5 сотрудников и приоритетная поддержка\"]', '{\"catalog\":50000,\"listings_per_day\":5000,\"sync_per_hour\":1,\"ai_infographic\":1000,\"ai_copy\":5000,\"ai_optimize\":5000,\"ai_tryon\":300,\"boosts\":100,\"staff\":5,\"analytics_months\":12,\"api\":1}', 'plan', 'period', 10, 1, 1, 1, 20, '2026-08-22 17:05:29'),
